with base as (select *, case when salary >= 128000 then 'High' when salary >= 71000 then 'Medium' else 'Low' end as salary_band, lower(level) as level_lower, coalesce(level, 'DIRECT') as level_clean from employees where hire_date >= date '2023-07-03' and level is not null), enriched as (select id, email, dept_id, salary, is_remote, level, level_lower, level_clean, ntile(5) over (partition by manager_id order by salary desc, id) as salary_bucket, last_value(level, true) over (partition by month(hire_date) order by hire_date, id rows between unbounded preceding and current row) as last_known_level from base), latest as (select *, row_number() over (partition by level order by salary desc, id) as latest_rank from enriched qualify latest_rank = 1), enriched_employees as (select id, email, dept_id, is_remote, level, level_lower, salary_bucket, last_known_level, lag(salary_bucket) over w_grp as prev_salary_bucket, lead(salary) over w_grp as next_salary, row_number() over w_grp as row_seq from latest where level not in ('L4', 'L5') window w_grp as (partition by level, dept_id order by salary_bucket, id)), scored as (select id, dept_id, is_remote, level, level_lower, salary_bucket, next_salary, min(next_salary) over (partition by level, dept_id order by prev_salary_bucket, id rows between 2 preceding and current row) as last3_min_next_salary, avg(next_salary) over (partition by level, dept_id order by prev_salary_bucket, id rows between 2 preceding and current row) as last3_avg_next_salary, sum(next_salary) over (partition by level, dept_id order by prev_salary_bucket, id rows between 2 preceding and current row) as last3_sum_next_salary from enriched_employees) select level, case when last3_min_next_salary >= 157000 then 'PREMIUM' else 'STANDARD' end as last3_min_next_salary_tier, sum(case when level = 'L1' then last3_min_next_salary else 0 end) as l1_last3_min_next_salary, sum(case when level = 'L4' then next_salary else 0 end) as l4_next_salary, sort_array(collect_set(level)) as level_list, approx_percentile(last3_avg_next_salary, 0.9) as last3_avg_next_salary_p90, sort_array(collect_set(level)) as level_list_2, count(distinct dept_id) as distinct_dept_ids from scored group by level, case when last3_min_next_salary >= 157000 then 'PREMIUM' else 'STANDARD' end order by l4_next_salary desc nulls last
